import type { Event, Operation } from "./contracts.js";

/** Stock CoS continuation messages are generated by the runtime, not T3. */
const AUTO_CONTINUATION =
  /^Continue the task from where you are\. \(Chat On Steroids starts a fresh turn every so often so long work stays reliable; nothing else changed\.\)$/;

export function isCoSContinuation(event: Event): boolean {
  return (
    event.kind === "user_message" &&
    typeof event.message?.text === "string" &&
    AUTO_CONTINUATION.test(event.message.text.trim())
  );
}

/** Skip revisions of prior turns when T3 is awaiting this particular input. */
export function belongsToInput(event: Event, operation?: Operation): boolean {
  if (!operation) return true;
  if (event.seq <= operation.baseline) return false;
  // CoS can publish a revision of an older message at a *new* event seq.
  // Its original position still precedes this T3 input's admission baseline.
  if (
    ["assistant_message", "tool_call", "agent_message"].includes(event.kind) &&
    event.position <= operation.baseline
  )
    return false;
  if (!event.turnId) return true;
  if (operation.turnId === event.turnId) return true;
  return operation.continuationTurnIds?.includes(event.turnId) ?? false;
}
